/* ============================================================
   أطياب الجاسم (React) — مشهد المبخرة ثلاثي الأبعاد (3DBakhour)

   القسم الثالث من الصفحة الرئيسية: المبخرة الحيّة (three.js + نموذج GLB
   مُدمج). المكوّن يعرض المسرح والعناصر التي تتوقّعها الحزمة بالمعرّفات
   نفسها (#mabkharaRoot · #mabkharaCanvas · #mabkharaLoader ·
   #mabkharaError · #mabkharaRetry · #mabkharaHint)، ثم يحمّل:

       home/mabkhara-config.js     ← window.mabkharaConfig
       home/mabkhara.bundle.js     ← المشهد (يقلع تلقائياً عند الاستيراد)

   ★ سياسة التحميل الكسول (كما في النسخة الأصلية): لا يُحمَّل المشهد
     (≈3.3 م.ب) إلا إذا اقترب قسمه من الشاشة، أو بعد تفاعل حقيقي من
     العميل (تمرير/لمس/ضغط) مع مهلة ٦ ثوانٍ — بلا تفاعل: لا يُحمَّل أبداً.
   ★ إعادة المحاولة هنا من React: نُدمّر العرض القديم (clone للـcanvas +
     dispose) ثم نُعيد الإقلاع، فلا حاجة لإعادة تحميل الصفحة.
   ★ الإقلاع يُعاد في كل تركيب: نصّ الحزمة يُجلب مرة واحدة ويُخزَّن، ثم
     يُنفَّذ عبر Blob برابط جديد — لأن وحدة ES لا تُنفَّذ مرتين بالرابط
     نفسه (كان سبب بقاء المسرح فارغاً بعد العودة إلى الرئيسية).
   ★ الأحداث: نستمع لـ mabkhara:ready / mabkhara:error، ونُطلق حدث
     atyab:route و resize عند ظهور القسم حتى يُعيد المشهد القياس والتشغيل.
   ============================================================ */

import { useCallback, useEffect, useRef, useState } from "react";
import { toUserMessage } from "../../api/friendlyError.js";
/* ملاحظة: التحميل الكسول يفحص القرب من الشاشة بأربع طرق متتالية:
     ١) IntersectionObserver بهامش ٩٠٠px      ٢) حدث التمرير بأي حاوية
     (capture: ليس window فقط)                ٣) أول تفاعل حقيقي من العميل
     ٤) فحص فوري عند التركيب/عند العودة للرئيسية.
   وهذه الأربعة لازمة لأن النسخة الأصلية كانت تعتمد على تمرير window وحده،
   فإذا وُضع الموقع داخل حاوية تمرير (embed/iframe) لا يصل أي إشارة أبداً. */
import { useNavigate } from "react-router-dom";
import { PATHS } from "../../routes.js";

const CONFIG_SRC = (process.env.PUBLIC_URL || "") + "/home/mabkhara-config.js";
const BUNDLE_SRC = (process.env.PUBLIC_URL || "") + "/home/mabkhara.bundle.js";

function loadScript(src, isModule, id, timeoutMs) {
  return new Promise(function (resolve, reject) {
    let done = false;
    let timer = 0;
    if (id) {
      const old = document.getElementById(id);
      if (old && old.parentNode) old.parentNode.removeChild(old);
    }
    const el = document.createElement("script");
    if (id) el.id = id;
    if (isModule) el.type = "module";
    else el.async = false;
    el.src = src;
    function finish(fn, arg) {
      if (done) return;
      done = true;
      if (timer) window.clearTimeout(timer);
      fn(arg);
    }
    el.onload = function () {
      finish(resolve, el);
    };
    el.onerror = function () {
      finish(reject, new Error("تعذّر تحميل " + src));
    };
    /* ★ إصلاح الخلل: <script> معلّق (شبكة بطيئة) لا يُطلق onload/onerror
       أبداً — كان الوعد يبقى معلّقاً حتى مهلة الـ30 ثانية العامة فيُظهر
       «انتهت مدة انتظار المشهد» بلا سبب واضح. الآن يفشل سريعاً برسالة. */
    try {
      timer = window.setTimeout(function () {
        if (el.parentNode) el.parentNode.removeChild(el);
        finish(reject, new Error("تعذّر تحميل " + src + " (انتهت المهلة)"));
      }, timeoutMs || 20000);
    } catch (e) {}
    document.body.appendChild(el);
  });
}

/* ★ إعادة الإقلاع بلا إعادة تنزيل:
   وحدة الـES modules تُخزَّن مؤقتاً، فإدراج الرابط نفسه مرة أخرى لا
   يُعيد تنفيذ الحزمة — وهو ما كان يُفرغ المسرح عند العودة إلى الصفحة
   الرئيسية (يبقى window.mabkhara موجهاً إلى <canvas> قديم مُفكَّك).
   الحل: نجلب نصّ الحزمة مرة واحدة لكل جلسة صفحة (من ذاكرة المتصفّح)،
   ثم نُعيد تنفيذها في كل إقلاع عبر Blob برابط جديد — فيُعاد التقييم
   دائماً بلا تنزيل ٣٫٣ م.ب. مرة أخرى. */
let bundleTextPromise = null;

function bundleText() {
  if (!bundleTextPromise) {
    bundleTextPromise = fetch(BUNDLE_SRC, { cache: "force-cache" })
      .then(function (res) {
        if (!res.ok) throw new Error("تعذّر تحميل ملفات المشهد (" + res.status + ")");
        const ct = res.headers.get("content-type") || "";
        if (ct.indexOf("text/html") !== -1) throw new Error("ملف المبخرة غير موجود في public/home — انسخ مجلد home من الحزمة");
        return res.text();
      })
      .then(function (text) {
        if (text.slice(0, 200).toLowerCase().indexOf("<!doctype") !== -1 || text.slice(0, 200).toLowerCase().indexOf("<html") !== -1) throw new Error("ملف المبخرة غير موجود في public/home — انسخ مجلد home من الحزمة");
        return text;
      })
      .catch(function (err) {
        bundleTextPromise = null;
        throw err;
      });
  }
  return bundleTextPromise;
}

function runBundle() {
  return bundleText().then(function (text) {
    const url = URL.createObjectURL(new Blob([text], { type: "text/javascript" }));
    return loadScript(url, true, "mabkharaBundleScript").then(
      function (el) {
        URL.revokeObjectURL(url);
        return el;
      },
      function (err) {
        URL.revokeObjectURL(url);
        throw err;
      }
    );
  });
}

/* ------------------------------------------------------------
   دورة حياة المشهد: إقلاع الحزمة غير متزامن (يقرأ النموذج ويبنيه)،
   فقد ينتهي بعد أن يكون المكوّن قد فُكِّك، فيبقى مشهد «يتيم» يشغل
   حلقة رسم وسياق WebGL بلا <canvas> في المستند. نُبقي مرجعاً لكل
   مشهد أُقلع فعلاً، ونُنهي كل مشهد لم يعد له canvas حالٍّ في الصفحة.
   ------------------------------------------------------------ */
const liveScenes = [];

function disposeScene(scene) {
  if (!scene) return;
  try {
    if (typeof scene.setRunning === "function") scene.setRunning(false);
  } catch (e) {
    /* لم يجهز */
  }
  try {
    const renderer = scene.renderer;
    if (renderer) {
      if (renderer.setAnimationLoop) renderer.setAnimationLoop(null);
      if (renderer.dispose) renderer.dispose();
      if (renderer.forceContextLoss) renderer.forceContextLoss();
    }
  } catch (e) {
    /* لم يجهز */
  }
}

function pruneScenes() {
  const current = document.getElementById("mabkharaCanvas");
  for (let i = liveScenes.length - 1; i >= 0; i--) {
    const scene = liveScenes[i];
    const canvas = scene && scene.renderer ? scene.renderer.domElement : null;
    if (!canvas || canvas !== current) {
      disposeScene(scene);
      liveScenes.splice(i, 1);
    }
  }
}

/* نُنهي المشهد السابق فوراً (تفكيك المكوّن أو إعادة الإقلاع) */
function stopScene() {
  const scene = window.mabkhara;
  if (scene) {
    const at = liveScenes.indexOf(scene);
    if (at !== -1) liveScenes.splice(at, 1);
    disposeScene(scene);
  }
  window.mabkhara = null;
  window.__mabkharaReady = false;
  window.__mabkharaError = null;
  pruneScenes();
}

/* يُبقي المشهد الحالي ويعالج أي مشهد قديم انتهى إقلاعه متأخراً */
window.addEventListener("mabkhara:ready", function () {
  const scene = window.mabkhara;
  if (scene && liveScenes.indexOf(scene) === -1) liveScenes.push(scene);
  pruneScenes();
});

function wake() {
  try {
    document.dispatchEvent(new CustomEvent("atyab:route", { detail: { route: "home" } }));
  } catch (e) {
    /* بيئة قديمة */
  }
  try {
    window.dispatchEvent(new Event("resize"));
  } catch (e) {
    /* تجاهل */
  }
}

export default function Bakhour3D(props) {
  const navigate = useNavigate();
  const rootRef = useRef(null);
  const pressRef = useRef(null);
  const startedRef = useRef(false);
  const watchdogRef = useRef(0);
  const [status, setStatus] = useState("idle"); /* idle | loading | ready | failed */
  const [detail, setDetail] = useState("");
  const disposedRef = useRef(false); /* فُكِّك المكوّن؟ (نتجاهل إقلاعاً انتهى متأخراً) */

  /* ---------- أحداث الحزمة ---------- */
  useEffect(
    function () {
      function onReady() {
        if (watchdogRef.current) {
          window.clearTimeout(watchdogRef.current);
          watchdogRef.current = 0;
        }
        try { if (window.console && window.console.info) window.console.info('[mabkhara] ready'); } catch (e) {}
        setStatus("ready");
        setDetail("");
        wake();
      }
      function onError(e) {
        if (watchdogRef.current) {
          window.clearTimeout(watchdogRef.current);
          watchdogRef.current = 0;
        }
        const err = e && e.detail;
        try { if (window.console && window.console.error) window.console.error('[mabkhara] error:', err); } catch (e2) {}
        setStatus("failed");
        setDetail(toUserMessage(err, "ar") || "تعذّر تحميل المشهد ثلاثي الأبعاد.");
      }
      window.addEventListener("mabkhara:ready", onReady);
      window.addEventListener("mabkhara:error", onError);
      return function () {
        window.removeEventListener("mabkhara:ready", onReady);
        window.removeEventListener("mabkhara:error", onError);
      };
    },
    []
  );

  /* ---------- التحميل ---------- */
  const start = useCallback(function () {
    if (startedRef.current) return;
    startedRef.current = true;
    setStatus("loading");
    setDetail("");
    /* لا نبقي مشهداً قديماً يعمل في <canvas> لم يعد في المستند */
    stopScene();
    if (watchdogRef.current) window.clearTimeout(watchdogRef.current);
    /* ★ إصلاح الخلل: 30 ثانية لا تكفي لتنزيل 3.3 م.ب + التنفيذ على شبكة
       بطيئة بعد تأخير البوابة الكسولة — كانت المهلة تنفد والمشهد سيعمل
       بعد ثوانٍ. الآن 60 ثانية، والتعافي تلقائي إن وصل mabkhara:ready. */
    watchdogRef.current = window.setTimeout(function () {
      if (window.__mabkharaError) return;
      setStatus(function (prev) {
        if (prev === "ready") return prev;
        setDetail("انتهت مدة انتظار المشهد — أعد المحاولة");
        return "failed";
      });
    }, 60000);

    loadScript(CONFIG_SRC, false, "mabkharaConfigScript")
      .then(function () {
        if (disposedRef.current) return null;
        return runBundle();
      })
      .catch(function (err) {
        if (disposedRef.current) return;
        setStatus("failed");
        setDetail(toUserMessage(err, "ar") || "تعذّر تحميل ملفات المشهد.");
      });
  }, []);

  /* ---------- التحميل الكسول: اقتراب القسم أو تفاعل العميل ---------- */
  useEffect(
    function () {
      if (startedRef.current) return undefined;
      const el = rootRef.current;
      if (!el) return undefined;

      let armTimer = 0;
      let io = null;
      let checks = [];

      function isVisible() {
        /* القسم مخفيّ داخل الفتحة غير النشطة؟ */
        if (el.closest("[hidden]")) return false;
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
      }

      function isNear() {
        if (!isVisible()) return false;
        const r = el.getBoundingClientRect();
        const h = window.innerHeight || 800;
        return r.top < h + 900 && r.bottom > -700;
      }

      function cleanup() {
        window.removeEventListener("scroll", onScroll, true);
        window.removeEventListener("scrollend", onScroll, true);
        ["wheel", "touchstart", "pointerdown", "keydown"].forEach(function (ev) {
          window.removeEventListener(ev, onInteract, true);
        });
        if (io) {
          io.disconnect();
          io = null;
        }
        checks.forEach(function (t) {
          window.clearTimeout(t);
        });
        checks = [];
      }

      function fire(delay) {
        if (armTimer) window.clearTimeout(armTimer);
        armTimer = window.setTimeout(start, delay || 300);
        cleanup();
      }

      function onInteract() {
        /* تفاعل حقيقي من العميل → نُحمّل بسرعة */
        fire(600);
      }

      function onScroll() {
        if (isNear()) fire(300);
      }

      if (!("IntersectionObserver" in window)) {
        /* بلا IntersectionObserver: نُحمّل بعد إطار واحد لا في جسم الـeffect */
        armTimer = window.setTimeout(start, 0);
        return function () {
          if (armTimer) window.clearTimeout(armTimer);
        };
      }

      io = new IntersectionObserver(
        function (entries) {
          entries.forEach(function (entry) {
            if (entry.isIntersecting) fire(300);
          });
        },
        { rootMargin: "900px 0px" }
      );
      io.observe(el);

      /* احتياط ١: التمرير في أي حاوية (capture) — وليس window وحده،
         لأن الصفحة قد تُعرض داخل حاوية تمرير (embed) فلا يُطلق window
         حدث scroll إطلاقاً. */
      window.addEventListener("scroll", onScroll, { passive: true, capture: true });
      window.addEventListener("scrollend", onScroll, { passive: true, capture: true });

      /* احتياط ٢: أول تفاعل حقيقي من العميل */
      ["wheel", "touchstart", "pointerdown", "keydown"].forEach(function (ev) {
        window.addEventListener(ev, onInteract, { passive: true, capture: true });
      });

      /* احتياط ٣: فحص فوري — قد يكون القسم ظاهراً أصلاً بدون أي حدث */
      if (isNear()) fire(350);

      /* احتياط ٤: الفحص الفوري قد يسبق استقرار التخطيط (تحميل الخطوط
         والصور يُنزل القسم فيدخل نطاق ٩٠٠px بعد التركيب بلا أي حدث
         تمرير/تفاعل). هنا نُعيد الفحص مرّات قليلة بعد التركيب — فإن
         كان القسم قريباً يُقلع المشهد، وإلا لا شيء (يبقى التحميل كسولاً). */
      checks = [600, 1500, 3000].map(function (ms) {
        return window.setTimeout(function () {
          if (isNear()) fire(200);
        }, ms);
      });

      /* احتياط ٥: إن لم يبدأ المشهد بعد استقرار الصفحة، نُقلعه من تلقائنا
         فلا يبقى «جارٍ التحميل…» بلا نهاية لمن لا يُمرّر القسم إلى الشاشة
         (نافذة قصيرة/طويلة، أو معاينة لا تقبل التمرير). نحترم «توفير
         البيانات» والاتصال البطيء (2g/3g) فنُبقي التحميل كسولاً تماماً
         هناك — والتمرير/التفاعل يبقى يُقلعه كما هو. */
      const conn = navigator.connection || {};
      const frugal = !!conn.saveData || /^(slow-2g|2g|3g)$/.test(conn.effectiveType || "");
      if (!frugal) {
        checks.push(
          window.setTimeout(function () {
            fire(300);
          }, 5000)
        );
      }

      return function () {
        cleanup();
        if (armTimer) window.clearTimeout(armTimer);
      };
    },
    [start, props.active]
  );

  /* ---------- قيادة حالة التشغيل: «ظاهر ⇒ يعمل · مخفي ⇒ يتوقّف» ----------
     لا نكتفي بحدث atyab:route ولا بـIntersectionObserver الخاص بالحزمة:
     ذاك يحتفظ بعَلَم `onScreen` قديم، فإذا سجّل «خارج الشاشة» مرة ثم عاد
     القسم إلى الشاشة بلا تغيّر جديد في التقارير يبقى المشهد متوقّفاً
     («تُحمّل المبخرة أول مرة ثم لا تعمل عند العودة»). هنا نحسب الظهور
     من getBoundingClientRect مباشرة عند كل تنقّل/تمرير/تغيير مقاس، ونقود
     setRunning() بأنفسنا — فيعمل المشهد بمجرد عودته إلى الشاشة، ويتوقّف
     (توفيراً للمعالج) حين يخرج منها أو تُخفى الرئيسية. */
  useEffect(
    function () {
      const el = rootRef.current;

      function visible() {
        if (props.active === false) return false;
        if (!el) return true;
        if (el.closest("[hidden]")) return false;
        const r = el.getBoundingClientRect();
        const h = window.innerHeight || 800;
        return r.width > 0 && r.height > 0 && r.top < h + 160 && r.bottom > -160;
      }

      function sync() {
        const scene = window.mabkhara;
        if (!scene || typeof scene.setRunning !== "function") return;
        try {
          scene.setRunning(visible());
        } catch (e) {
          /* المشهد لم يجهز بعد */
        }
      }

      function kick() {
        if (props.active !== false) wake();
        sync();
      }

      kick();
      const timers = [120, 700, 1600].map(function (ms) {
        return window.setTimeout(kick, ms);
      });

      const io =
        el && "IntersectionObserver" in window
          ? new IntersectionObserver(function () {
              sync();
            }, { rootMargin: "160px" })
          : null;
      if (io) io.observe(el);

      window.addEventListener("scroll", sync, { passive: true, capture: true });
      window.addEventListener("resize", sync, { passive: true });
      document.addEventListener("atyab:route", sync);

      return function () {
        timers.forEach(function (t) {
          window.clearTimeout(t);
        });
        if (io) io.disconnect();
        window.removeEventListener("scroll", sync, true);
        window.removeEventListener("resize", sync);
        document.removeEventListener("atyab:route", sync);
      };
    },
    [props.active, status]
  );

  useEffect(
    function () {
      disposedRef.current = false;
      return function () {
        disposedRef.current = true;
        if (watchdogRef.current) window.clearTimeout(watchdogRef.current);
        watchdogRef.current = 0;
        /* تفكيك المكوّن: نُنهي المشهد فوراً (وإلا بقي يرسم في canvas منفصل) */
        stopScene();
      };
    },
    []
  );

  /* ---------- إعادة المحاولة (من React، بلا إعادة تحميل الصفحة) ---------- */
  const retry = useCallback(function () {
    /* canvas جديد بنفس المعرّف: الحزمة تقرأ المعرّف عند الإقلاع، فلا
       يُعاد استعمال canvas له سياق WebGL قديم. */
    const canvas = document.getElementById("mabkharaCanvas");
    if (canvas && canvas.parentNode) canvas.parentNode.replaceChild(canvas.cloneNode(false), canvas);
    stopScene();
    startedRef.current = false;
    setStatus("idle");
    setDetail("");
    /* إعادة التحميل فوراً: نحن في معالج نقر (لا داخل effect) */
    start();
  }, [start]);

  /* ---------- نقرة واحدة (بلا سحب) تفتح صفحة البخور ---------- */
  const resetPress = useCallback(function () {
    pressRef.current = null;
  }, []);

  const onPointerDown = useCallback(function (e) {
    pressRef.current = { x: e.clientX, y: e.clientY, t: Date.now(), target: e.target };
  }, []);

  const onPointerUp = useCallback(
    function (e) {
      const start = pressRef.current;
      pressRef.current = null;
      if (!start) return;
      if (Math.abs(e.clientX - start.x) > 8 || Math.abs(e.clientY - start.y) > 8) return;
      if (Date.now() - start.t > 700) return;
      if (start.target && start.target.closest && start.target.closest("button, a, input, select, label")) return;
      navigate(PATHS.incense);
    },
    [navigate]
  );

  return (
    <div className="void-frame showcase-media">
      <span className="scene-tag">
        <i /> المبخرة الثلاثية · مشهد حيّ
      </span>
      <div className="incense-stage">
        <div
          className="mabkhara-root"
          id="mabkharaRoot"
          ref={rootRef}
          role="link"
          tabIndex={0}
          title="انقر لعرض كل البخور"
          aria-label="مشهد المبخرة — انقر لعرض كل البخور"
          onPointerDown={onPointerDown}
          onPointerUp={onPointerUp}
          onPointerCancel={resetPress}
          onKeyDown={function (e) {
            if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") {
              e.preventDefault();
              navigate(PATHS.incense);
            }
          }}
        >
          <canvas id="mabkharaCanvas" />
          <div className="mabkhara-loader" id="mabkharaLoader" hidden={status === "ready" || status === "failed"}>
            <span className="mabkhara-ring" />
            <span className="mabkhara-loader-text">جارٍ تحميل المشهد…</span>
          </div>
          <div className="mabkhara-error" id="mabkharaError" hidden={status !== "failed"}>
            <p>تعذّر تحميل المشهد ثلاثي الأبعاد.</p>
            <span className="mabkhara-error-detail">{detail}</span>
            <button className="mabkhara-retry" type="button" onClick={retry}>
              إعادة المحاولة
            </button>
          </div>
          <div className="mabkhara-hint" id="mabkharaHint">
            اسحب لتدوير المبخرة · عجلة الفأرة للتقريب · انقر لعرض كل البخور
          </div>
        </div>
      </div>
    </div>
  );
}
